def installer(apps, schema_editor):
    Experience = apps.get_model('experiences', 'ExperienceModel')
    for ordre, (photo, cat, nom, nom_en, tag, tag_en, ville, prix, gratuit, desc, desc_en) in enumerate(GUIDE):
        credit, source = CREDITS[photo]
        champs = dict(
            categorie=cat, nom_en=nom_en, etiquette=tag, etiquette_en=tag_en, pays="Togo", pays_en="Togo", prix=prix, gratuit=gratuit,
            image_url=f"{PHOTOS}{photo}.jpg", credit_photo=credit, credit_photo_url=source, description=desc, description_en=desc_en, ordre=ordre,
        )
        existante = Experience.objects.filter(nom=nom, ville=ville).first()
        if not existante:
            Experience.objects.create(nom=nom, ville=ville, **champs)
        elif not existante.image and existante.image_url.startswith(PHOTO_GUIDE_INITIAL):
            # The one entry of the first guide still untouched in the back-office: anything else is left as it was edited
            Experience.objects.filter(pk=existante.pk).update(**champs)


class Migration(migrations.Migration):
    dependencies = [('experiences', '0003_credit_photo')]
    operations = [migrations.RunPython(installer, migrations.RunPython.noop)]
